-- open required access grants -> client todos (waiting on client)
insert into public.work_items (client_id, phase_id, type, title, client_text, status, waiting_on, since, accountable_id, doer_id, visibility, source, source_id)
select g.client_id, (select id from work_phases p where p.client_id=g.client_id and p.status='current' limit 1), 'client_todo',
       'Zugang: ' || g.platform, 'Bitte gib uns Zugang: ' || g.platform, 'waiting', 'client', g.updated_at::date, (select id from work_actors where name='Martin' and client_id is null limit 1),
       (select id from work_actors a where a.kind='client' and a.client_id=g.client_id limit 1), 'client', 'access', g.id::text
from access_grants g join clients c on c.id=g.client_id
where g.required and g.status not in ('erteilt','geprueft','entfaellt') and c.name not like 'Testpraxis%'
on conflict (source, source_id) do nothing;

